initJs:
function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    const users = await window.aivicApi.list(0); // ログインユーザーテーブル
    const userSelect = container.querySelector("#select-user");
    if (users) {
      users.forEach(user => {
        const option = document.createElement("option");
        option.value = user.ユーザーID;
        option.textContent = user.ユーザー名 || user.ログインID;
        userSelect.appendChild(option);
      });
    }
  }

  // 操作履歴一覧を描画
  function renderHistories(histories) {
    const tbody = container.querySelector("#history-tbody");
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    if (pageHistories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted);">該当する操作履歴が見つかりませんでした</td></tr>';
    } else {
      tbody.innerHTML = pageHistories.map(history => `
        <tr data-id="${history.操作履歴ID}">
          <td>${formatDateTime(history.操作日時)}</td>
          <td>${history.ユーザー名 || ''}</td>
          <td>${history.操作種別 || ''}</td>
          <td>${history.操作画面 || ''}</td>
          <td>${history.IPアドレス || ''}</td>
          <td><span class="status-badge ${getResultClass(history.処理結果)}">${history.処理結果 || ''}</span></td>
          <td><button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button></td>
        </tr>
      `).join('');
    }

    updatePagination(histories.length);
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }

  // 処理結果のクラス
  function getResultClass(result) {
    switch(result) {
      case '成功': return 'success';
      case '失敗': return 'error';
      case 'エラー': return 'error';
      default: return '';
    }
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector("#page-info");
    const btnPrev = container.querySelector("#btn-prev");
    const btnNext = container.querySelector("#btn-next");

    pageInfo.textContent = `${currentPage} / ${totalPages || 1}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // 検索フィルター
  function applyFilters() {
    const dateStart = container.querySelector("#date-start").value;
    const dateEnd = container.querySelector("#date-end").value;
    const userId = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付範囲バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert('開始日が終了日より後の日付になっています。正しい日付範囲を入力してください。');
      return;
    }

    // IPアドレス形式バリデーション
    if (ipAddress && !isValidIPAddress(ipAddress)) {
      alert('不正なIPアドレス形式です。正しい形式で入力してください。');
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (dateStart || dateEnd) {
        const historyDate = new Date(history.操作日時);
        if (dateStart && historyDate < new Date(dateStart)) return false;
        if (dateEnd && historyDate > new Date(dateEnd + ' 23:59:59')) return false;
      }

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名フィルター
      if (screenName && !history.操作画面?.toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && history.IPアドレス !== ipAddress) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // IPアドレス形式チェック
  function isValidIPAddress(ip) {
    const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    return ipRegex.test(ip);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector("#date-start").value = '';
    container.querySelector("#date-end").value = '';
    container.querySelector("#select-user").value = '';
    container.querySelector("#select-operation-type").value = '';
    container.querySelector("#input-screen-name").value = '';
    container.querySelector("#input-ip-address").value = '';
    container.querySelector("#select-result").value = '';

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // CSV出力
  function exportCSV() {
    if (filteredHistories.length === 0) {
      alert('出力するデータがありません。');
      return;
    }

    if (filteredHistories.length > 100000) {
      alert('データ量が多すぎるため、CSV出力できません。検索条件を絞り込んでください。');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', 'IPアドレス', '処理結果', '操作内容'];
    const csvContent = [
      headers.join(','),
      ...filteredHistories.map(history => [
        `"${formatDateTime(history.操作日時)}"`,
        `"${history.ユーザー名 || ''}"`,
        `"${history.操作種別 || ''}"`,
        `"${history.操作画面 || ''}"`,
        `"${history.IPアドレス || ''}"`,
        `"${history.処理結果 || ''}"`,
        `"${(history.操作内容 || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    container.querySelector("#detail-id").textContent = history.操作履歴ID || '';
    container.querySelector("#detail-datetime").textContent = formatDateTime(history.操作日時);
    container.querySelector("#detail-user").textContent = history.ユーザー名 || '';
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-processing-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    container.querySelector("#detail-modal").classList.remove('hidden');
  }

  // 初期データ読み込み
  async function loadData() {
    const histories = await window.aivicApi.list(13); // システム操作履歴テーブル
    if (histories) {
      // ユーザー名を結合
      const users = await window.aivicApi.list(0);
      const userMap = {};
      if (users) {
        users.forEach(user => {
          userMap[user.ユーザーID] = user.ユーザー名 || user.ログインID;
        });
      }

      allHistories = histories.map(history => ({
        ...history,
        ユーザー名: userMap[history.ユーザーID] || ''
      })).sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));

      filteredHistories = [...allHistories];
      renderHistories(filteredHistories);
    } else {
      allHistories = tables[13]?.records || [];
      filteredHistories = [...allHistories];
      renderHistories(filteredHistories);
    }
  }

  // イベントリスナー設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  // 詳細ボタンとモーダル
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }

    const closeBtn = e.target.closest("#btn-close-modal");
    if (closeBtn) {
      container.querySelector("#detail-modal").classList.add('hidden');
    }
  });

  // モーダル背景クリックで閉じる
  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target === container.querySelector("#detail-modal")) {
      container.querySelector("#detail-modal").classList.add('hidden');
    }
  });

  // 初期化
  loadUsers();
  loadData();
}
